 const title=o.status==='not_measured'?'History not started':warning?'Monitoring needs attention':'Collecting reliability evidence';
 $('#operations').innerHTML='<p><span class="badge '+(warning?'amber':'')+'">'+escape(title)+'</span></p><p>'+c.completed+' completed · '+c.failed+' failed · '+c.quota_paused+' quota pauses · '+c.abandoned+' interrupted scans in the measured window.</p><p class="small">Recording since '+escape(time(o.measured_since))+' · '+Number(o.elapsed_days).toFixed(1)+' of at least 14 observation days. This does not yet certify reliability or matching accuracy.</p><p class="small">Longest recorded wait after a scan became due: '+o.max_start_delay_minutes+' min. '+o.browse_requests+' Browse request attempts recorded; other workflows also use the quota.</p><p class="small">Catch-up trigger last seen: '+escape(time(o.trigger_last_seen_at))+(o.trigger_stale?' · heartbeat missing or late':'')+'. '+o.dispatches.correlated+' dispatches linked to worker scans.</p>'+(o.history_truncated?'<p>History exceeds this view’s limit. Counts are incomplete.</p>':'');
