 const image=photos.length?'<a class="hero-photo" href="'+escape(photos[photo])+'" target="_blank" rel="noreferrer"><img loading="'+(i===0?'eager':'lazy')+'" src="'+escape(photos[photo])+'" alt="Listing photo '+(photo+1)+' of '+photos.length+'"><span class="photo-error" hidden>Photo couldn’t load. Open the listing to check its images.</span></a>'+(photos.length>1?'<div class="photo-thumbs" role="group" aria-label="Listing photos">'+photos.map((u,j)=>'<button class="'+(photo===j?'selected':'')+'" data-photo="'+i+'|'+j+'" aria-label="Show photo '+(j+1)+'" aria-pressed="'+(photo===j)+'"><img loading="lazy" src="'+escape(u)+'" alt=""></button>').join('')+'</div>':'')+'<p class="photo-caption">Photo '+(photo+1)+' of '+photos.length+' · seller provided</p>':'<div class="photo-empty"><span class="record" aria-hidden="true">◉</span><strong>'+(r.evidence_stale?'Fresh photos needed':'No photos available')+'</strong><p>'+(invalidation?escape(invalidation):r.evidence_stale?'Older seller content is withheld until the listing is refreshed.':'Check the listing or ask the seller for label and runout photos.')+'</p></div>';
